# Questões inéditas escritas por IA (Claude), no estilo das bancas. Não são de prova real.
# Cada uma traz gabarito e comentário com a base legal. Ficam separadas das provas reais.
DA, DC, LP, RLM = 'Direito Administrativo', 'Direito Constitucional', 'Língua Portuguesa', 'Raciocínio Lógico e Matemática'
AFO, ADM, GP, ETI = 'AFO e Orçamento Público', 'Administração Geral e Pública', 'Gestão de Pessoas', 'Ética e Integridade'

CE = [  # estilo Cebraspe: julgue o item
 (DC, 'Concurso público', 'A investidura em cargo em comissão declarado em lei de livre nomeação e exoneração dispensa a aprovação prévia em concurso público.', 'C',
  'Gabarito C. A CF, art. 37, II, exige concurso para cargo ou emprego público, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração.'),
 (DC, 'Concurso público', 'O prazo de validade do concurso público será de até dois anos, prorrogável uma única vez por até quatro anos.', 'E',
  'Gabarito E. Pela CF, art. 37, III, a validade é de até dois anos, prorrogável uma vez por igual período, e não por até quatro anos.'),
 (DC, 'Estabilidade', 'São estáveis após dois anos de efetivo exercício os servidores nomeados para cargo de provimento efetivo em virtude de concurso público.', 'E',
  'Gabarito E. Desde a EC 19/1998, a CF, art. 41, fixa três anos de efetivo exercício para a estabilidade, e exige avaliação especial de desempenho.'),
 (DA, 'Lei 8.112: posse e exercício', 'É de quinze dias o prazo para o servidor empossado em cargo público entrar em exercício, contados da data da posse.', 'C',
  'Gabarito C. Lei 8.112/1990, art. 15, § 1º: é de quinze dias o prazo para entrar em exercício, contados da posse. A posse, por sua vez, ocorre em até trinta dias da publicação do ato de provimento (art. 13, § 1º).'),
 (DA, 'Lei 8.112: posse e exercício', 'A posse em cargo público pode ser realizada mediante procuração específica.', 'C',
  'Gabarito C. Lei 8.112/1990, art. 13, § 3º: a posse poderá dar-se mediante procuração específica.'),
 (DA, 'Lei 8.112: penalidades', 'Nos termos da Lei 8.112/1990, a penalidade de suspensão não poderá exceder noventa dias.', 'C',
  'Gabarito C. Art. 130 da Lei 8.112/1990: a suspensão será aplicada em caso de reincidência das faltas punidas com advertência e não poderá exceder noventa dias.'),
 (DA, 'Lei 9.784: recursos', 'Salvo disposição legal específica, é de quinze dias o prazo para interposição de recurso administrativo no âmbito da Lei 9.784/1999.', 'E',
  'Gabarito E. Lei 9.784/1999, art. 59: salvo disposição legal específica, o prazo para recurso é de dez dias, contado da ciência ou divulgação oficial da decisão.'),
 (DA, 'Lei 9.784: recursos', 'O recurso administrativo tramitará, no máximo, por três instâncias administrativas, salvo disposição legal diversa.', 'C',
  'Gabarito C. É a regra literal do art. 57 da Lei 9.784/1999.'),
 (DA, 'Lei 9.784: anulação', 'O direito da administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em cinco anos, contados da data em que foram praticados, salvo comprovada má-fé.', 'C',
  'Gabarito C. Lei 9.784/1999, art. 54. No caso de efeitos patrimoniais contínuos, o prazo conta da percepção do primeiro pagamento (§ 1º).'),
 (DA, 'Lei 14.133: modalidades', 'A Lei 14.133/2021 manteve a tomada de preços e o convite entre as modalidades de licitação.', 'E',
  'Gabarito E. O art. 28 da Lei 14.133/2021 prevê pregão, concorrência, concurso, leilão e diálogo competitivo. Tomada de preços e convite deixaram de existir.'),
 (DA, 'Lei 14.133: fases', 'Como regra, na Lei 14.133/2021, a fase de habilitação antecede a fase de julgamento das propostas.', 'E',
  'Gabarito E. Pelo art. 17 da Lei 14.133/2021, o julgamento vem antes da habilitação. A inversão é exceção, admitida mediante ato motivado e prevista no edital (art. 17, § 1º).'),
 (DC, 'Direitos e garantias', 'São gratuitas as ações de habeas corpus e habeas data e, na forma da lei, os atos necessários ao exercício da cidadania.', 'C',
  'Gabarito C. Literal da CF, art. 5º, LXXVII.'),
 (DC, 'Direitos e garantias', 'Por determinação judicial, é permitido o ingresso na casa do indivíduo, sem o consentimento do morador, durante a noite.', 'E',
  'Gabarito E. CF, art. 5º, XI: sem consentimento, só se entra em flagrante delito, desastre, para prestar socorro ou, durante o dia, por determinação judicial.'),
 (DC, 'Direitos políticos', 'A idade mínima de trinta anos é condição de elegibilidade para o cargo de senador.', 'E',
  'Gabarito E. CF, art. 14, § 3º, VI: 35 anos para Presidente, Vice e Senador; 30 para Governador e Vice; 21 para deputado, prefeito e vice e juiz de paz; 18 para vereador.'),
 (DC, 'Emendas à Constituição', 'A forma republicana de governo figura expressamente entre as cláusulas pétreas da Constituição Federal de 1988.', 'E',
  'Gabarito E. O art. 60, § 4º, protege a forma federativa de Estado, o voto direto, secreto, universal e periódico, a separação dos Poderes e os direitos e garantias individuais. A forma republicana não está nesse rol.'),
 (DC, 'Processo legislativo', 'É vedada a edição de medida provisória sobre matéria relativa a direito penal.', 'C',
  'Gabarito C. CF, art. 62, § 1º, I, “b”: é vedada a MP sobre direito penal, processual penal e processual civil.'),
 (LP, 'Crase', 'Na frase “O chefe entregou o relatório a ela”, o emprego do sinal indicativo de crase antes do pronome seria obrigatório.', 'E',
  'Gabarito E. Não há crase antes de pronome pessoal reto ou oblíquo, porque esses pronomes não admitem artigo.'),
 (ETI, 'LGPD', 'De acordo com a LGPD, o dado referente à filiação a sindicato é dado pessoal sensível.', 'C',
  'Gabarito C. Lei 13.709/2018, art. 5º, II: são sensíveis os dados sobre origem racial ou étnica, convicção religiosa, opinião política, filiação a sindicato ou a organização de caráter religioso, filosófico ou político, saúde, vida sexual, dado genético ou biométrico.'),
 (ETI, 'LAI', 'A informação classificada no grau reservado tem prazo máximo de restrição de acesso de quinze anos.', 'E',
  'Gabarito E. Lei 12.527/2011, art. 24, § 1º: ultrassecreta, 25 anos; secreta, 15 anos; reservada, 5 anos.'),
 (RLM, 'Negação da condicional', 'A negação da proposição “Se chove, então a rua fica molhada” é “Chove e a rua não fica molhada”.', 'C',
  'Gabarito C. A negação de “se P, então Q” é “P e não Q”.'),
 (ETI, 'Improbidade administrativa', 'Após a Lei 14.230/2021, admite-se a responsabilização por ato de improbidade a título de culpa nos casos de lesão ao erário.', 'E',
  'Gabarito E. Com a Lei 14.230/2021, todos os atos de improbidade exigem dolo (Lei 8.429/1992, art. 1º, §§ 1º a 3º). A modalidade culposa do art. 10 foi extinta.'),
 (DC, 'Poder Judiciário', 'Os juízes de primeiro grau adquirem a vitaliciedade após dois anos de exercício.', 'C',
  'Gabarito C. CF, art. 95, I: a vitaliciedade, no primeiro grau, só é adquirida após dois anos de exercício.'),
]

FCC = [  # estilo FCC: letra da lei, cinco alternativas
 (DA, 'Lei 8.112: provimento', 'De acordo com a Lei 8.112/1990, NÃO é forma de provimento de cargo público:',
  ['readaptação.', 'reversão.', 'transferência.', 'recondução.', 'aproveitamento.'], 'C',
  'Gabarito C. O art. 8º lista nomeação, promoção, readaptação, reversão, aproveitamento, reintegração e recondução. A transferência foi revogada e declarada inconstitucional, porque permitia ingresso em outra carreira sem concurso.'),
 (DA, 'Lei 8.112: provimento', 'A reinvestidura do servidor estável no cargo anteriormente ocupado, ou no cargo resultante de sua transformação, quando invalidada a sua demissão por decisão administrativa ou judicial, com ressarcimento de todas as vantagens, denomina-se',
  ['reintegração.', 'recondução.', 'reversão.', 'readaptação.', 'aproveitamento.'], 'A',
  'Gabarito A. É a definição de reintegração no art. 28 da Lei 8.112/1990. Recondução é o retorno ao cargo anterior por inabilitação em estágio probatório ou pela reintegração do anterior ocupante (art. 29).'),
 (DA, 'Lei 8.112: provimento', 'O retorno do servidor estável ao cargo anteriormente ocupado, decorrente de inabilitação em estágio probatório relativo a outro cargo, denomina-se',
  ['reversão.', 'recondução.', 'reintegração.', 'readaptação.', 'disponibilidade.'], 'B',
  'Gabarito B. Lei 8.112/1990, art. 29, I. A reversão é o retorno do aposentado (art. 25).'),
 (DA, 'Lei 8.112: licenças', 'Após cada quinquênio de efetivo exercício, o servidor poderá, no interesse da Administração, afastar-se do exercício do cargo efetivo, com a respectiva remuneração, para participar de curso de capacitação profissional, por até',
  ['seis meses.', 'dois meses.', 'um ano.', 'três meses.', 'quarenta e cinco dias.'], 'D',
  'Gabarito D. Lei 8.112/1990, art. 87: licença para capacitação de até três meses a cada quinquênio.'),
 (DA, 'Lei 8.112: penalidades', 'Nos termos da Lei 8.112/1990, configura abandono de cargo a ausência intencional do servidor ao serviço por mais de',
  ['quinze dias consecutivos.', 'trinta dias consecutivos.', 'sessenta dias, interpoladamente, durante doze meses.', 'trinta dias, interpoladamente, durante seis meses.', 'noventa dias consecutivos.'], 'B',
  'Gabarito B. Art. 138: abandono é a ausência intencional por mais de trinta dias consecutivos. Sessenta dias interpolados em doze meses, sem causa justificada, é inassiduidade habitual (art. 139).'),
 (DA, 'Lei 8.112: deveres e proibições', 'Considere as condutas abaixo. Constitui DEVER do servidor, nos termos da Lei 8.112/1990:',
  ['representar contra ilegalidade, omissão ou abuso de poder.', 'retirar, sem prévia anuência da autoridade competente, qualquer documento da repartição.', 'promover manifestação de apreço ou desapreço no recinto da repartição.', 'recusar fé a documentos públicos.', 'cometer a pessoa estranha à repartição o desempenho de atribuição de sua responsabilidade.'], 'A',
  'Gabarito A. Representar contra ilegalidade, omissão ou abuso de poder é dever (art. 116, XII). As demais alternativas são proibições do art. 117 (incisos II, V, III e VI).'),
 (DA, 'Lei 9.784: direitos do administrado', 'Segundo a Lei 9.784/1999, é direito do administrado perante a Administração:',
  ['ser obrigatoriamente assistido por advogado em qualquer processo administrativo.', 'ter vista dos autos somente após a decisão final.', 'formular alegações e apresentar documentos antes da decisão, os quais serão objeto de consideração pelo órgão competente.', 'recusar-se a prestar as informações que lhe forem solicitadas.', 'obter a anulação de qualquer ato que lhe seja desfavorável.'], 'C',
  'Gabarito C. Art. 3º, III. A assistência por advogado é facultativa, salvo quando a lei a exigir (art. 3º, IV); ter vista dos autos é direito durante o processo (art. 3º, II); e prestar informações é dever (art. 4º, IV).'),
 (DA, 'Lei 9.784: prazos', 'Conforme a Lei 9.784/1999, os prazos expressos em dias',
  ['contam-se apenas em dias úteis.', 'incluem o dia do começo e excluem o do vencimento.', 'contam-se de modo contínuo.', 'suspendem-se nos feriados.', 'só começam a correr após a publicação no Diário Oficial, em qualquer hipótese.'], 'C',
  'Gabarito C. Art. 66, § 2º: os prazos em dias contam-se de modo contínuo. O caput manda excluir o dia do começo e incluir o do vencimento.'),
 (DA, 'Lei 9.784: decisão', 'Concluída a instrução de processo administrativo, a Administração tem o prazo de até',
  ['quinze dias para decidir, improrrogáveis.', 'trinta dias para decidir, salvo prorrogação por igual período expressamente motivada.', 'sessenta dias para decidir, prorrogáveis uma vez.', 'dez dias para decidir, salvo motivo de força maior.', 'noventa dias para decidir, sem possibilidade de prorrogação.'], 'B',
  'Gabarito B. Lei 9.784/1999, art. 49.'),
 (DC, 'Poder Judiciário', 'Nos termos da Constituição Federal, NÃO é órgão do Poder Judiciário:',
  ['o Conselho Nacional de Justiça.', 'o Tribunal Superior do Trabalho.', 'os Juízes Militares.', 'os Tribunais Regionais Federais.', 'o Tribunal de Contas da União.'], 'E',
  'Gabarito E. O art. 92 da CF lista os órgãos do Judiciário. O TCU é órgão que auxilia o Congresso Nacional no controle externo (art. 71) e não integra o Judiciário.'),
 (DC, 'Justiça do Trabalho', 'Os Tribunais Regionais do Trabalho compõem-se de, no mínimo,',
  ['cinco juízes.', 'nove juízes.', 'sete juízes.', 'onze juízes.', 'quinze juízes.'], 'C',
  'Gabarito C. CF, art. 115: no mínimo sete juízes, recrutados, quando possível, na respectiva região. A mesma regra vale para os TRFs (art. 107).'),
 (DC, 'Justiça do Trabalho', 'O Tribunal Superior do Trabalho compõe-se de',
  ['onze Ministros.', 'quinze Ministros.', 'vinte e um Ministros.', 'vinte e sete Ministros.', 'trinta e três Ministros.'], 'D',
  'Gabarito D. CF, art. 111-A. Não confunda: STF tem 11 ministros e o STJ, no mínimo, 33.'),
 (LP, 'Concordância verbal', 'A concordância verbal está correta em:',
  ['Haviam muitos processos pendentes na vara.', 'Fazem dois anos que o concurso foi realizado.', 'Existem, no setor, servidores capacitados para a tarefa.', 'Devem haver soluções para o problema.', 'Aluga-se salas comerciais no centro da cidade.'], 'C',
  'Gabarito C. “Existir” é pessoal e concorda com “servidores”. “Haver” no sentido de existir e “fazer” indicando tempo são impessoais (“Havia”, “Faz”), e a impessoalidade passa ao auxiliar (“Deve haver”). Em “Alugam-se salas”, o verbo concorda com o sujeito paciente.'),
 (LP, 'Crase', 'O sinal indicativo de crase está empregado corretamente em:',
  ['O servidor começou à trabalhar cedo.', 'Entregou o documento à uma colega.', 'Referiu-se à Vossa Excelência com respeito.', 'Os atendimentos ocorrem de segunda à sexta-feira.', 'Compareceu à reunião convocada pela diretoria.'], 'E',
  'Gabarito E. “Comparecer a” + “a reunião” gera crase. Não há crase antes de verbo, de artigo indefinido, de pronome de tratamento como Vossa Excelência, nem em “de segunda a sexta”, onde a preposição “de” pede “a” sem artigo.'),
 (RLM, 'Equivalências lógicas', 'Uma proposição logicamente equivalente a “Se Ana é analista, então Bruno é técnico” é:',
  ['Se Bruno é técnico, então Ana é analista.', 'Se Ana não é analista, então Bruno não é técnico.', 'Ana é analista e Bruno não é técnico.', 'Se Bruno não é técnico, então Ana não é analista.', 'Ana não é analista e Bruno é técnico.'], 'D',
  'Gabarito D. A contrapositiva (se não Q, então não P) é equivalente à condicional. As opções A e B são a recíproca e a inversa, que não são equivalentes; a C é a negação.'),
 (RLM, 'Porcentagem', 'O preço de um equipamento sofreu um aumento de 20% e, em seguida, uma redução de 20%. Em relação ao preço inicial, o preço final é',
  ['igual.', '4% maior.', '2% menor.', '4% menor.', '20% menor.'], 'D',
  'Gabarito D. 1,20 × 0,80 = 0,96, ou seja, 4% abaixo do preço inicial.'),
 (DA, 'Lei 14.133: julgamento', 'NÃO é critério de julgamento previsto na Lei 14.133/2021:',
  ['menor preço.', 'maior desconto.', 'maior retorno econômico.', 'técnica e preço.', 'menor prazo de entrega.'], 'E',
  'Gabarito E. O art. 33 prevê menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance (no leilão) e maior retorno econômico.'),
 (DC, 'CNJ', 'O Conselho Nacional de Justiça compõe-se de',
  ['quinze membros, com mandato de dois anos, admitida uma recondução.', 'onze membros vitalícios.', 'nove membros, com mandato de quatro anos.', 'quinze membros vitalícios, nomeados pelo Presidente do STF.', 'treze membros, com mandato de três anos, vedada a recondução.'], 'A',
  'Gabarito A. CF, art. 103-B: quinze membros com mandato de dois anos, admitida uma recondução. O CNJ é presidido pelo Presidente do STF.'),
 (AFO, 'Despesa pública', 'Nos termos da Lei 4.320/1964, a verificação do direito adquirido pelo credor, tendo por base os títulos e documentos comprobatórios do respectivo crédito, corresponde ao estágio da despesa denominado',
  ['empenho.', 'liquidação.', 'pagamento.', 'fixação.', 'programação.'], 'B',
  'Gabarito B. Art. 63 da Lei 4.320/1964. O empenho cria a obrigação de pagamento (art. 58) e o pagamento só ocorre após a regular liquidação (art. 62).'),
 (DA, 'Lei 8.112: penalidades', 'Segundo a Lei 8.112/1990, a ação disciplinar prescreverá em',
  ['cinco anos, quanto à advertência.', '180 dias, quanto à suspensão.', 'dois anos, quanto à demissão.', '180 dias, quanto à advertência.', 'cinco anos, quanto à suspensão.'], 'D',
  'Gabarito D. Art. 142: cinco anos para demissão, cassação e destituição; dois anos para suspensão; 180 dias para advertência.'),
]

FGV = [  # estilo FGV: caso prático
 (DA, 'Lei 8.112: provimento', 'Maria, servidora pública federal estável, foi demitida após processo disciplinar. Anos depois, decisão judicial invalidou a demissão. O cargo que ela ocupava estava provido por João, também servidor estável. Nesse cenário, de acordo com a Lei 8.112/1990, é correto afirmar que',
  ['Maria será reconduzida, e João será exonerado de ofício.', 'Maria será reintegrada, e João será reconduzido ao cargo de origem, sem direito a indenização, ou aproveitado em outro cargo, ou posto em disponibilidade.', 'Maria será aproveitada em outro cargo, porque o seu está ocupado.', 'Maria será reintegrada, e João terá direito a indenização pela perda do cargo.', 'Maria só poderá retornar se houver cargo vago, cabendo-lhe apenas indenização.'], 'B',
  'Gabarito B. Lei 8.112/1990, art. 28, § 2º: encontrando-se provido o cargo, o ocupante, se estável, será reconduzido ao cargo de origem, sem direito a indenização, ou aproveitado em outro cargo, ou posto em disponibilidade.'),
 (DA, 'Atos administrativos', 'O servidor Carlos, sem competência para tanto, praticou ato administrativo cuja competência não era exclusiva da autoridade superior. O ato não lesou o interesse público nem causou prejuízo a terceiros. Diante disso, a Administração',
  ['deve obrigatoriamente anular o ato, sem possibilidade de aproveitamento.', 'pode convalidar o ato, por se tratar de defeito sanável.', 'deve revogar o ato, com efeitos retroativos.', 'só pode desfazer o ato mediante decisão judicial.', 'deve aguardar o prazo decadencial de cinco anos para que o ato se torne válido.'], 'B',
  'Gabarito B. Lei 9.784/1999, art. 55: atos com defeitos sanáveis, sem lesão ao interesse público nem prejuízo a terceiros, podem ser convalidados pela Administração. O vício de competência não exclusiva é o exemplo clássico de defeito sanável.'),
 (DA, 'Atos administrativos', 'Determinada secretaria concedeu, de forma válida, autorização de uso de espaço público a uma associação. Meses depois, por razões de conveniência e oportunidade, decidiu desfazer o ato. Trata-se de',
  ['anulação, com efeitos ex tunc.', 'revogação, com efeitos ex nunc, respeitados os direitos adquiridos.', 'cassação, por descumprimento de condições.', 'convalidação, com efeitos ex nunc.', 'anulação, que só pode ser feita pelo Poder Judiciário.'], 'B',
  'Gabarito B. Revogação é a retirada de ato válido por conveniência e oportunidade, com efeitos ex nunc e respeito aos direitos adquiridos (Súmula 473 do STF e Lei 9.784/1999, art. 53). A anulação recai sobre atos ilegais.'),
 (DC, 'Responsabilidade civil do Estado', 'Um motorista de órgão público federal, em serviço, colidiu com o carro de Paulo, causando-lhe danos. Paulo deseja ser indenizado. Segundo a Constituição e a jurisprudência do STF, Paulo deve',
  ['ajuizar a ação contra o motorista, que responde de forma objetiva.', 'ajuizar a ação contra a União, que responde objetivamente, cabendo a ela ação regressiva contra o motorista em caso de dolo ou culpa.', 'ajuizar a ação contra a União e o motorista, obrigatoriamente em litisconsórcio.', 'provar a culpa do motorista para responsabilizar a União.', 'pedir a indenização apenas na via administrativa.'], 'B',
  'Gabarito B. CF, art. 37, § 6º: responsabilidade objetiva do Estado, com regresso contra o agente nos casos de dolo ou culpa. O STF (Tema 940) fixou que a ação deve ser proposta contra o ente, e não diretamente contra o agente.'),
 (DA, 'Lei 14.133: contratação direta', 'O Município Alfa pretende contratar, para a festa de aniversário da cidade, show de cantor consagrado pela crítica especializada e pela opinião pública, por meio de seu empresário exclusivo. Nos termos da Lei 14.133/2021, a contratação deve ocorrer por',
  ['dispensa de licitação, em razão do valor.', 'concorrência, com critério de melhor técnica.', 'inexigibilidade de licitação, por inviabilidade de competição.', 'pregão eletrônico.', 'concurso, com prêmio ao vencedor.'], 'C',
  'Gabarito C. Art. 74, II, da Lei 14.133/2021: é inexigível a licitação para contratar profissional do setor artístico, diretamente ou por empresário exclusivo, desde que consagrado pela crítica especializada ou pela opinião pública.'),
 (DA, 'Lei 14.133: contratação direta', 'Após enchente que destruiu parte de uma escola, o Estado Beta contratou empresa, com dispensa de licitação, para obras emergenciais. De acordo com a Lei 14.133/2021, esse contrato',
  ['pode durar até cinco anos, prorrogáveis.', 'deve ser concluído no prazo máximo de um ano, contado da ocorrência da emergência, vedadas a prorrogação e a recontratação da mesma empresa com base nessa hipótese.', 'pode ser prorrogado uma vez, por igual período.', 'deve ser concluído em até 180 dias, admitida uma prorrogação.', 'não tem prazo máximo, porque a emergência dispensa limites.'], 'B',
  'Gabarito B. Lei 14.133/2021, art. 75, VIII. Na lei antiga (8.666) o prazo era de 180 dias; na nova é de um ano, vedadas a prorrogação e a recontratação.'),
 (DC, 'Remédios constitucionais', 'Ana requereu a um órgão federal acesso às informações sobre sua pessoa constantes de banco de dados governamental, e o pedido foi negado. Para assegurar o conhecimento dessas informações, o remédio constitucional adequado é o',
  ['mandado de segurança.', 'habeas corpus.', 'mandado de injunção.', 'habeas data.', 'ação popular.'], 'D',
  'Gabarito D. CF, art. 5º, LXXII: habeas data assegura o conhecimento de informações relativas à pessoa do impetrante em registros ou bancos de dados de entidades governamentais ou de caráter público.'),
 (DC, 'Remédios constitucionais', 'Uma norma constitucional garante determinado direito, mas depende de lei regulamentadora que nunca foi editada, o que impede o seu exercício. O instrumento cabível para suprir a omissão no caso concreto é o',
  ['mandado de injunção.', 'habeas data.', 'mandado de segurança coletivo.', 'ação civil pública.', 'habeas corpus.'], 'A',
  'Gabarito A. CF, art. 5º, LXXI: concede-se mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais.'),
 (DA, 'Princípios', 'O Prefeito do Município Gama nomeou o próprio cunhado para cargo em comissão de assessor no gabinete. À luz da Súmula Vinculante 13 do STF, a nomeação',
  ['é válida, porque o cargo em comissão é de livre nomeação.', 'é válida, porque o cunhado é parente apenas por afinidade.', 'viola a Constituição, porque alcança parentes em linha reta, colateral ou por afinidade até o terceiro grau, inclusive.', 'só seria inválida se o cunhado não tivesse qualificação técnica.', 'viola a Constituição apenas se houver prejuízo ao erário.'], 'C',
  'Gabarito C. A Súmula Vinculante 13 veda a nomeação de cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade até o terceiro grau, inclusive, da autoridade nomeante. O cunhado é parente por afinidade em 2º grau.'),
 (LP, 'Coesão e conectivos', 'Na frase “Os servidores chegaram cedo; eles, no entanto, não encontraram o chefe na sala”, o conectivo “no entanto” estabelece relação de',
  ['causa.', 'conclusão.', 'oposição.', 'finalidade.', 'condição.'], 'C',
  'Gabarito C. “No entanto” é conjunção adversativa, equivalente a “mas” e “porém”: expressa oposição entre as ideias.'),
 (LP, 'Vozes verbais', 'A frase “O relatório foi elaborado pela equipe de auditoria” está corretamente transposta para a voz ativa em:',
  ['A equipe de auditoria elaborou o relatório.', 'Elaborou-se o relatório pela equipe de auditoria.', 'O relatório elaborou a equipe de auditoria.', 'A equipe de auditoria foi elaborada pelo relatório.', 'Tinha sido elaborado o relatório pela equipe de auditoria.'], 'A',
  'Gabarito A. Na voz ativa, o agente da passiva (“pela equipe”) vira sujeito, e o verbo mantém o tempo (“foi elaborado” → “elaborou”).'),
 (RLM, 'Lógica de argumentação', 'Considere verdadeiras as afirmações: “Todo analista é graduado” e “Carlos não é graduado”. Com base nelas, é necessariamente verdadeiro que',
  ['Carlos é analista.', 'Carlos não é analista.', 'algum graduado não é analista.', 'Carlos é técnico.', 'nenhum graduado é analista.'], 'B',
  'Gabarito B. Se todo analista é graduado e Carlos não é graduado, Carlos não pode ser analista (modus tollens). As demais conclusões não decorrem das premissas.'),
 (RLM, 'Análise combinatória', 'Um tribunal precisa formar uma comissão de 3 servidores escolhidos entre 6 candidatos, sem distinção de função na comissão. O número de comissões diferentes possíveis é',
  ['18.', '120.', '20.', '216.', '36.'], 'C',
  'Gabarito C. Combinação de 6 elementos, 3 a 3: 6!/(3!·3!) = 20. A ordem não importa, por isso não é arranjo (120).'),
 (AFO, 'Créditos adicionais', 'Durante a execução do orçamento, um órgão precisou realizar despesa para a qual não havia dotação orçamentária específica, sem que se tratasse de situação urgente e imprevisível. O crédito adicional adequado é o',
  ['suplementar.', 'extraordinário.', 'especial.', 'complementar.', 'de antecipação de receita.'], 'C',
  'Gabarito C. Lei 4.320/1964, art. 41: créditos especiais são destinados a despesas sem dotação orçamentária específica. Suplementares reforçam dotação existente; extraordinários atendem despesas urgentes e imprevistas (guerra, comoção interna, calamidade).'),
 (ADM, 'Desempenho', 'Um programa estadual de qualificação cumpriu todas as metas de cursos previstas, gastou menos que o orçado e, dois anos depois, verificou-se aumento real da renda e da empregabilidade dos participantes. Esse último resultado, de transformação na realidade dos beneficiários, refere-se à',
  ['eficiência.', 'eficácia.', 'economicidade.', 'efetividade.', 'legalidade.'], 'D',
  'Gabarito D. Eficiência relaciona recursos e resultados; eficácia é atingir as metas; efetividade é o impacto real na sociedade.'),
 (GP, 'Avaliação de desempenho', 'Um tribunal adotou um modelo de avaliação em que cada servidor recebe feedback da chefia, dos colegas, dos subordinados e dos usuários atendidos, além de fazer sua autoavaliação. Esse método é conhecido como',
  ['escala gráfica.', 'incidentes críticos.', 'avaliação 360 graus.', 'escolha forçada.', 'avaliação por objetivos.'], 'C',
  'Gabarito C. A avaliação 360 graus reúne a percepção de todos que interagem com o avaliado.'),
 (DA, 'Lei 8.112: remoção', 'Lúcia é servidora federal. Seu marido, também servidor federal, foi deslocado de ofício, no interesse da Administração, para outra cidade. Nos termos da Lei 8.112/1990, Lúcia',
  ['não pode ser removida, porque a remoção depende sempre do interesse da Administração.', 'pode ser removida a pedido, para acompanhar o cônjuge, independentemente do interesse da Administração.', 'deve pedir redistribuição de seu cargo.', 'pode ser removida apenas se houver vaga e concordância da chefia.', 'deve pedir licença sem remuneração, única opção prevista.'], 'B',
  'Gabarito B. Lei 8.112/1990, art. 36, parágrafo único, III, “a”: remoção a pedido, independentemente do interesse da Administração, para acompanhar cônjuge ou companheiro, também servidor, deslocado no interesse da Administração.'),
 (DA, 'Lei 9.784: impedimento e suspeição', 'Em processo administrativo, verificou-se que o servidor responsável pela instrução tem amizade íntima com o interessado. Segundo a Lei 9.784/1999, trata-se de hipótese de',
  ['impedimento, que gera nulidade absoluta de todos os atos.', 'suspeição, que pode ser arguida.', 'incompetência absoluta.', 'conflito de competência.', 'situação irrelevante, se não houver prova de favorecimento.'], 'B',
  'Gabarito B. Art. 20: pode ser arguida a suspeição de quem tenha amizade íntima ou inimizade notória com algum dos interessados. O impedimento (art. 18) envolve interesse direto na matéria, participação como perito, testemunha ou representante, e litígio com o interessado.'),
 (ETI, 'LAI', 'Um cidadão pediu a um tribunal informações sobre contratos firmados no último ano. O servidor exigiu que ele explicasse os motivos do pedido. Segundo a Lei 12.527/2011, a exigência é',
  ['válida, para evitar pedidos abusivos.', 'válida, se o pedido envolver valores acima de R$ 1 milhão.', 'vedada, porque não se pode exigir motivação do pedido de informação de interesse público.', 'válida apenas para pessoas jurídicas.', 'vedada apenas se o pedido for feito pessoalmente.'], 'C',
  'Gabarito C. Art. 10, § 3º: são vedadas quaisquer exigências relativas aos motivos determinantes da solicitação de informações de interesse público.'),
 (DC, 'Administração Pública', 'O servidor Pedro, ocupante de cargo efetivo de analista, pretende acumular esse cargo com um de professor em universidade pública, havendo compatibilidade de horários. Segundo a Constituição, a acumulação é',
  ['vedada em qualquer hipótese.', 'permitida independentemente de compatibilidade de horários, por se tratar de um cargo de professor com outro técnico ou científico.', 'permitida apenas se ambos forem de professor.', 'permitida, desde que a soma das remunerações não ultrapasse o teto e que o cargo de analista seja de nível técnico ou científico.', 'permitida somente com autorização do tribunal de contas.'], 'D',
  'Gabarito D. CF, art. 37, XVI, “b”: é permitida a acumulação de um cargo de professor com outro técnico ou científico, havendo compatibilidade de horários e respeitado o teto do inciso XI. A alternativa que dispensa a compatibilidade de horários está errada, porque ela é requisito expresso.'),
]
